+import type { NotificationThreadStorePort } from "../ports/notification-thread-store.port.js";
+
+function featureKey(workspaceId: string, featureId: string): string {
+  return `slack:feature_thread:${workspaceId}:${featureId}`;
+}
+
+function taskKey(workspaceId: string, featureId: string, taskId: string): string {
+  return `slack:task_thread:${workspaceId}:${featureId}:${taskId}`;
+}
+
+function taskKeyPrefix(workspaceId: string, featureId: string): string {
+  return `slack:task_thread:${workspaceId}:${featureId}:`;
+}
+
+/** In-memory store for unit tests. Thread-safe enough for single-threaded Node. */
+export class InMemoryThreadStore implements NotificationThreadStorePort {
+  private store = new Map<string, string>();
+
+  async getFeatureThread(workspaceId: string, featureId: string): Promise<string | null> {
+    return this.store.get(featureKey(workspaceId, featureId)) ?? null;
+  }
+
+  async setFeatureThread(workspaceId: string, featureId: string, threadTs: string): Promise<void> {
+    this.store.set(featureKey(workspaceId, featureId), threadTs);
+  }
+
+  async deleteFeatureThread(workspaceId: string, featureId: string): Promise<void> {
+    this.store.delete(featureKey(workspaceId, featureId));
+  }
+
+  async getTaskThread(workspaceId: string, featureId: string, taskId: string): Promise<string | null> {
+    return this.store.get(taskKey(workspaceId, featureId, taskId)) ?? null;
+  }
+
+  async setTaskThread(workspaceId: string, featureId: string, taskId: string, threadTs: string): Promise<void> {
+    this.store.set(taskKey(workspaceId, featureId, taskId), threadTs);
+  }
+
+  async deleteTaskThread(workspaceId: string, featureId: string, taskId: string): Promise<void> {
+    this.store.delete(taskKey(workspaceId, featureId, taskId));
+  }
+
+  async deleteAllTaskThreads(workspaceId: string, featureId: string): Promise<void> {
+    const prefix = taskKeyPrefix(workspaceId, featureId);
+    for (const key of [...this.store.keys()]) {
+      if (key.startsWith(prefix)) {
+        this.store.delete(key);
+      }
+    }
+  }
+
+  /** Inspection helper for tests. */
+  snapshot(): Record<string, string> {
+    return Object.fromEntries(this.store);
+  }
+
+  clear(): void {
+    this.store.clear();
+  }
+}
